-- =============================================================================
-- Studuel — Migration 225 : LE PROGRAMME DE PHILOSOPHIE (Tle)
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main.
--    Source : scripts/contenu/*.mjs
--    Regénérer : node scripts/seed-contenu.mjs --num 225 --slugs philosophie
--
-- CONSTAT MESURÉ (node _ASSOCIE/sonde-contenu.mjs, 05/08/2026) : la
-- philosophie Tle n'avait que 5 chapitres, taillés dans un découpage maison
-- (« La conscience et l'inconscient », « La vérité et la raison »…) qui ne
-- correspond à AUCUNE des notions au programme du baccalauréat. Un élève qui
-- révisait « le devoir », « la technique » ou « le temps » ne trouvait rien.
-- Cette migration installe les 17 notions officielles, la liberté étant
-- éclatée en trois chapitres (indépendance / libre arbitre / liberté
-- politique) — soit 19 chapitres.
--
-- Cette migration apporte : 19 chapitres, 19 leçons,
-- 19 quiz et 152 questions, sur 1 matière.
--
-- CHOIX ASSUMÉS :
--  · tous les quiz sont `is_free = true`. Aucun compte ne peut aujourd’hui
--    passer `tier1` (aucun paiement n’existe), donc un quiz payant serait un
--    quiz INVISIBLE pour 100 % des élèves — le contraire du but ;
--  · chaque cours porte des sections `##`, ce qui rend sa carte mentale
--    dérivable (cf. lib/mind-map-auto) : aucune tuile ne promet dans le vide.
--
-- Idempotent : les UUID sont dérivés du contenu (SHA-1), donc stables ; les
-- INSERT sont tous gardés par ON CONFLICT DO NOTHING. Rejouable sans risque.
--
-- PRÉREQUIS : 002, 008, 191, 193 exécutées (les matières doivent exister).
-- À exécuter dans : Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

-- 0. Ménage ----------------------------------------------------------------
-- [philosophie] La file « À revoir » d'abord : review_items.item_id n'a PAS de clé
-- [philosophie] étrangère (il pointe soit une question, soit une carte). Rien ne casse si on
-- [philosophie] l'oublie — le lecteur écarte déjà un contenu disparu — mais le compteur
-- [philosophie] « X à revoir » continuerait de compter des questions qui n'existent plus.
DELETE FROM public.review_items ri
 USING public.quiz_questions qq, public.quizzes qz, public.lessons l,
       public.chapters c, public.subjects s
 WHERE ri.item_kind = 'question'
   AND ri.item_id = qq.id
   AND qq.quiz_id = qz.id
   AND qz.lesson_id = l.id
   AND l.chapter_id = c.id
   AND c.subject_id = s.id
   AND s.slug = 'philosophie'
   AND c.level = 'Tle'
   AND l.title IN ('L''essentiel du cours', 'Exercices types');

-- [philosophie] Les quiz ensuite : quizzes.lesson_id est ON DELETE SET NULL, donc
-- [philosophie] supprimer le chapitre laisserait derrière lui des quiz orphelins, rattachés à
-- [philosophie] aucune leçon mais toujours servis par le moteur de révision.
DELETE FROM public.quizzes q
 USING public.lessons l, public.chapters c, public.subjects s
 WHERE q.lesson_id = l.id
   AND l.chapter_id = c.id
   AND c.subject_id = s.id
   AND s.slug = 'philosophie'
   AND c.level = 'Tle'
   AND l.title IN ('L''essentiel du cours', 'Exercices types');

-- [philosophie] Puis les chapitres : leçons, fiches de révision, supports, progression
-- [philosophie] et chapitres cochés partent en cascade (toutes les clés étrangères vers
-- [philosophie] chapters et lessons sont ON DELETE CASCADE).
DELETE FROM public.chapters c
 USING public.subjects s
 WHERE c.subject_id = s.id
   AND s.slug = 'philosophie'
   AND c.level = 'Tle'
   AND EXISTS (
     SELECT 1 FROM public.lessons l
      WHERE l.chapter_id = c.id
        AND l.title IN ('L''essentiel du cours', 'Exercices types')
   );

-- 1. Chapitres -------------------------------------------------------------
